// Expected body:
// { bill_to_id, ship_to_id, ship_branch, price_branch, order_status,
//   ship_via, ship_date, required_date, po, release, internal_notes,
//   shipping_instructions, freight_in, writer, outside_sales, email,
//   lines: [{ productId, quantity, um?, umQuantity?, unitPrice?, comments? }] }
const b = $input.first().json.body || {};
const lines = (Array.isArray(b.lines) ? b.lines : [])
  .map((l) => ({
    productId: Number(l.productId),
    quantity: Math.round(Number(l.quantity) || 0),
    um: l.um || 'ea',
    umQuantity: Number(l.umQuantity) || 1,
    unitPrice: l.unitPrice != null && l.unitPrice !== '' ? Number(l.unitPrice) : null,
    // Line comment, sent to Eclipse as lineItemProduct.comments.
    comments: String(l.comments == null ? '' : l.comments).trim(),
  }))
  .filter((l) => l.productId && l.quantity > 0);
const fail = (msg) => [{ json: { ok: false, statusCode: 400, body: { success: false, error: msg, step: 'validate' } } }];
if (!b.bill_to_id) return fail('Missing bill_to_id');
if (!b.ship_to_id) return fail('Missing ship_to_id');
if (!b.writer) return fail('Missing writer (e_user_id)');
if (!lines.length) return fail('Add at least one line with a quantity.');
// Freight in, dollars; blank, invalid or negative → 0 (not sent).
const freight = Number(b.freight_in);
const isoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : '';
return [{ json: { ok: true, input: {
  billToId: String(b.bill_to_id), shipToId: String(b.ship_to_id),
  shipBranch: String(b.ship_branch || ''), priceBranch: String(b.price_branch || ''),
  orderStatus: String(b.order_status || 'Bid'), shipVia: String(b.ship_via || ''),
  shipDate: isoDate(b.ship_date), requiredDate: isoDate(b.required_date),
  po: String(b.po || ''), release: String(b.release || ''),
  internalNotes: String(b.internal_notes || ''), shippingInstructions: String(b.shipping_instructions || ''),
  writer: String(b.writer).toUpperCase(), outsideSales: String(b.outside_sales || ''),
  email: String(b.email || ''), lines,
  freightIn: isFinite(freight) && freight > 0 ? Math.round(freight * 100) / 100 : 0,
} } }];

// Field names follow the post_sorder() reference script. Rep-entered
// values win; customer defaults fill the gaps.
const inp = $('Validate').first().json.input;
const billEnv = $('Eclipse: get bill-to').first().json;
const shipEnv = $input.first().json;
const fail = (msg, step) => [{ json: { ok: false, statusCode: 502, body: { success: false, error: msg, step } } }];
if (billEnv.error) return fail('Eclipse bill-to lookup failed: ' + billEnv.error + ' ' + JSON.stringify(billEnv.message || ''), 'getBillTo');
if (shipEnv.error) return fail('Eclipse ship-to lookup failed: ' + shipEnv.error + ' ' + JSON.stringify(shipEnv.message || ''), 'getShipTo');
const bill = (Array.isArray(billEnv.results) ? billEnv.results[0] : billEnv) || {};
const ship = (Array.isArray(shipEnv.results) ? shipEnv.results[0] : shipEnv) || {};
if (!bill.id) return fail('Eclipse customer ' + inp.billToId + ' not found.', 'getBillTo');
if (!ship.id) return fail('Eclipse customer ' + inp.shipToId + ' not found.', 'getShipTo');
if (bill.isBillTo === false) return fail('Customer ' + bill.id + ' is not a Bill-To customer.', 'validate');
if (ship.isShipTo === false) return fail('Customer ' + ship.id + ' is not a Ship-To customer.', 'validate');

const val = (v) => (v && typeof v === 'object') ? (v.id || v.code || v.name || '') : (v == null ? '' : String(v));
// Defaults when the page sends blank dates: ship today, required 7 days
// out, pushed to Monday if that lands on a weekend.
const ymd = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const today = new Date();
const req = new Date(); req.setDate(req.getDate() + 7);
if (req.getDay() === 6) req.setDate(req.getDate() + 2);
else if (req.getDay() === 0) req.setDate(req.getDate() + 1);
const homeBranch = val(bill.homeBranch);

const order = {
  priceBranch: inp.priceBranch || homeBranch,
  shipBranch: inp.shipBranch || homeBranch,
  billToCustomer: bill.id,
  shipToCustomer: ship.id,
  orderStatus: inp.orderStatus,
  salesSource: val(bill.salesSourceOverride) || 'Default Sales', // bill-to's, else 'Default Sales'
  shipDate: inp.shipDate || ymd(today),
  requiredDate: inp.requiredDate || ymd(req),
  customerPONumber: inp.po || val(bill.defaultPoNumber),
  customerReleaseNumber: inp.release,
  insideSalesPerson: '',
  outsideSalesPerson: inp.outsideSales || val(bill.outsideSalesperson) || 'WIHOUSE',
  writer: inp.writer,
  orderType: 'MOE',
  email: inp.email,
  street1: ship.addressLine1 || '',
  street2: ship.addressLine2 || '',
  city: ship.city || '',
  state: ship.state || '',
  postalCode: ship.postalCode || '',
  country: ship.countryCode || '',
  internalNotes: inp.internalNotes,
  shippingInstructions: inp.shippingInstructions,
  shipIds: [ship.id],
  lines: inp.lines.map((l) => {
    const p = { productId: l.productId, quantity: l.quantity, um: l.um, umQuantity: l.umQuantity };
    if (l.unitPrice != null && isFinite(l.unitPrice)) p.unitPrice = l.unitPrice;
    // Line comment, with commentsId '1' as in the user's lineItemProduct
    // sample (UNVERIFIED what other ids mean; exports show commentTypeId '1').
    if (l.comments) { p.comments = l.comments; p.commentsId = '1'; }
    return { lineItemProduct: p };
  }),
};
// Ship via only when the rep picked one (a bid may leave it blank); no
// customer-default fallback, Eclipse decides what a missing shipVia means.
if (inp.shipVia) order.shipVia = inp.shipVia;
// Freight in from the page's totals box, as Eclipse's freightCharges (the
// only freight field in the post_sorder() reference body). UNVERIFIED that
// Eclipse books it as freight in (freightInBillable) and not freight out.
if (inp.freightIn > 0) order.freightCharges = inp.freightIn;
// Terms from the bill-to; left out when the bill-to has none.
if (val(bill.defaultTerms)) order.termsCode = val(bill.defaultTerms);
return [{ json: { ok: true, order } }];

// Eclipse returns the created order wrapped as { results: [order] }, with
// id "S2737687" and generations[].generationId (verified 2026-10-17). The
// e_sorder_id is <id>.<first generation, 4-digit padded>, e.g. S2737687.0001.
const env = $input.first().json;
const r = Array.isArray(env.results) ? (env.results[0] || {}) : env;
const order = $('Build order').first().json.order;
if (env.error) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createSalesOrder',
    error: 'Eclipse POST /SalesOrders failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 800), request: order } } }];
}
const rawId = String(r.id || r.eclipseOid || '');
const base = rawId.split('.')[0];
const gens = Array.isArray(r.generations) ? r.generations : [];
const genFromId = rawId.includes('.') ? rawId.split('.')[1] : '';
const gen = String(genFromId || (gens[0] && gens[0].generationId) || 1).padStart(4, '0');
if (!base) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createSalesOrder',
    error: 'Eclipse created the order but returned no order id: ' + JSON.stringify(env).substring(0, 500) } } }];
}
return [{ json: { ok: true, orderId: base, e_sorder_id: base + '.' + gen, e_sorder_ids: [base + '.' + gen], eclipse: r } }];

const c = $('Check order').first().json;
let r = $input.first().json || {};
// A non-JSON content type lands the body in `data` as text; parse it.
if (!r.orders && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
// update-hs-deal answers { message, source, orders: [{ <hs_deal_id>: <e_sorder_id> }] }
// (verified 2026-10-17); pick the deal whose order id is the one just created
// (exact, or same order ignoring the gen suffix), else the only deal returned.
const pairs = [];
for (const o of (Array.isArray(r.orders) ? r.orders : [])) {
  for (const [dealId, soId] of Object.entries(o || {})) pairs.push([String(dealId), String(soId)]);
}
const base = (id) => String(id || '').split('.')[0].toUpperCase();
const hit = pairs.find((p) => p[1] === c.e_sorder_id) || pairs.find((p) => base(p[1]) === base(c.e_sorder_id)) || (pairs.length === 1 ? pairs[0] : null);
const hsDealId = hit ? hit[0] : '';
return [{ json: { statusCode: 200, body: {
  success: true,
  e_sorder_id: c.e_sorder_id,
  order_id: c.orderId,
  hs_deal_id: hsDealId,
  // orders: what update-hs-deal returned, kept for troubleshooting a missing deal link.
  hubspot_sync: r.error ? { ok: false, error: String(r.error) } : { ok: true, orders: r.orders || null },
} } }];
